const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const P = [];
for (let i = 0; i < 7; i++) {
    P.push({ x: input[2 * i], y: input[2 * i + 1] });
}
const [P1, P2, P3, P4, P5, P6, P7] = P;

function dist2(A, B) {
    const dx = A.x - B.x;
    const dy = A.y - B.y;
    return dx * dx + dy * dy;
}

function cross(A, B, C) {
    return (B.x - A.x) * (C.y - A.y) - (B.y - A.y) * (C.x - A.x);
}

let ok = true;

// 1. Ângulo ∠P2P1P3 agudo
const v12 = { x: P2.x - P1.x, y: P2.y - P1.y };
const v13 = { x: P3.x - P1.x, y: P3.y - P1.y };
if (v12.x * v13.x + v12.y * v13.y <= 0) ok = false;

// 2. |P1P2| = |P1P3|
if (dist2(P1, P2) !== dist2(P1, P3)) ok = false;

// 3. P2, P3, P4, P5 colineares
if (cross(P2, P3, P4) !== 0 || cross(P2, P3, P5) !== 0) ok = false;

// 4. Pontos médios de P2P3 e P4P5 coincidem
if (P2.x + P3.x !== P4.x + P5.x || P2.y + P3.y !== P4.y + P5.y) ok = false;

// 5. |P2P3| > |P4P5|
if (dist2(P2, P3) <= dist2(P4, P5)) ok = false;

// 6. P4P6 e P5P7 perpendiculares a P2P3
const dx = P3.x - P2.x;
const dy = P3.y - P2.y;
if ((P6.x - P4.x) * dx + (P6.y - P4.y) * dy !== 0) ok = false;
if ((P7.x - P5.x) * dx + (P7.y - P5.y) * dy !== 0) ok = false;

// 7. |P4P6| = |P5P7|
if (dist2(P4, P6) !== dist2(P5, P7)) ok = false;

// 8. P1 e P6 separados pela reta P2P3
const c1 = cross(P2, P3, P1);
const c6 = cross(P2, P3, P6);
if (!((c1 > 0 && c6 < 0) || (c1 < 0 && c6 > 0))) ok = false;

console.log(ok ? 'S' : 'N');
